cd /case && perl -0pi -e 's/(    refinementBox\n    \{\n        type box;\n        min  \(-1\.0 -3\.5 -1\.0\);\n        max  \( 2\.5 3\.5 1\.0\);\n    \}\n\})/$1\n    leBox\n    {\n        type box;\n        min  (-0.1 -3.1 -0.2);\n        max  ( 0.3 3.1 0.2);\n    }\n}/' system/snappyHexMeshDict && perl -0pi -e 's/(        refinementBox\n        \{\n            mode inside;\n            levels \(\(1E15 4\)\);\n        \}\n    \})/$1\n        leBox\n        {\n            mode inside;\n            levels ((1E15 6));\n        }\n    }/' system/snappyHexMeshDict && grep -n -A4 'leBox' system/snappyHexMeshDict | head -12
